import sympy
import math
import itertools
import functools

class RingMock:
    def __init__(self, name, is_domain, has_accp, is_ufd, ufd_locs):
        self.name = name
        self.is_domain = is_domain
        self.has_accp = has_accp
        self.is_ufd = is_ufd
        self.ufd_locs = ufd_locs

    def __str__(self):
        return self.name

    def __repr__(self):
        return self.name

# Standard counterexamples for Nagata's Criterion without "S generated by primes"
Z_sqrt_minus_5 = RingMock("Z[sqrt(-5)]", True, True, False, [2, '2'])
Z_xy_zw = RingMock("Z[x,y,z,w]/(xy-zw)", True, True, False, ['x', 'y', 'z', 'w'])
Z_2i = RingMock("Z[2i]", True, True, False, [2, '2'])
k_t2_t3 = RingMock("k[t^2,t^3]", True, True, False, ['t^2', 't**2', 't'])

def conditions(witness) -> list[bool]:
    h1 = False
    h2 = False
    neg_q = False
    
    try:
        # Witness is expected to be a tuple (R, S) where R is the ring and S is the localized element/set
        if isinstance(witness, tuple) and len(witness) == 2:
            R, S = witness
        else:
            R = witness
            S = None
            
        # 1. Check if R is one of our mock objects
        if hasattr(R, 'is_domain') and hasattr(R, 'has_accp'):
            h1 = bool(R.is_domain and R.has_accp)
            h2 = False
            for loc in getattr(R, 'ufd_locs', []):
                if str(loc) == str(S):
                    h2 = True
                    break
                if isinstance(S, (list, tuple, set)):
                    if any(str(loc) == str(x) for x in S):
                        h2 = True
                        break
            neg_q = not bool(R.is_ufd)
            return [h1, h2, neg_q]
            
        # 2. Check if R is a dictionary representation
        if isinstance(R, dict):
            h1 = bool(R.get('is_domain', False) and R.get('has_accp', False))
            h2 = False
            for loc in R.get('ufd_locs', []):
                if str(loc) == str(S):
                    h2 = True
                    break
                if isinstance(S, (list, tuple, set)):
                    if any(str(loc) == str(x) for x in S):
                        h2 = True
                        break
            neg_q = not bool(R.get('is_ufd', True))
            return [h1, h2, neg_q]
            
        # 3. Check if R is a SymPy domain (e.g., ZZ, QQ)
        if hasattr(R, 'is_UFD') and not hasattr(R, 'has_accp'):
            h1 = True # Standard SymPy domains (ZZ, QQ, etc.) have ACCP
            if R.is_UFD:
                h2 = True
                neg_q = False
            else:
                h2 = False
                neg_q = True
            return [h1, h2, neg_q]
            
        # 4. Fallback to string matching for common mathematical notations
        R_str = str(R).replace(" ", "").lower()
        S_str = str(S).replace(" ", "").lower() if S is not None else ""
        
        if "sqrt(-5)" in R_str or "sqrt(5)*i" in R_str:
            h1 = True
            h2 = ("2" in S_str)
            neg_q = True
            
        elif "xy-zw" in R_str or "xy=zw" in R_str:
            h1 = True
            h2 = any(t in S_str for t in ['x', 'y', 'z', 'w'])
            neg_q = True
            
        elif "x**2+y**2+z**2-1" in R_str or "x^2+y^2+z^2-1" in R_str:
            h1 = True
            h2 = ("x-1" in S_str or "1-x" in S_str)
            neg_q = True
            
        elif "z[2i]" in R_str or "z[2*i]" in R_str:
            h1 = True
            h2 = ("2" in S_str)
            neg_q = True
            
        elif ("t**2" in R_str and "t**3" in R_str) or ("t^2" in R_str and "t^3" in R_str):
            h1 = True
            h2 = ("t**2" in S_str or "t^2" in S_str or "t" in S_str)
            neg_q = True
            
    except Exception:
        pass
        
    return [h1, h2, neg_q]

